SELECT c.config_id, c.material_id, m.material_code, m.material_name, c.cost_method, c.tax_included, c.effective_date, c.company_id, c.status, c.create_by, c.create_time, c.update_by, c.update_time, c.remark FROM fin_cost_method_config c LEFT JOIN wms_material m ON m.material_id = c.material_id AND m.del_flag = '0'
AND m.material_code LIKE CONCAT('%', #{materialCode}, '%')
AND c.cost_method = #{costMethod}
AND c.status = #{status}
AND c.del_flag = '0'
ORDER BY c.material_id IS NULL DESC, m.material_code

